mapper.select:
select id as customer_id, customer_name, phone,
  (select name from t_user where t_user.id = t_customer.owner_id) as owner_name
from t_customer
where (customer_status is null or customer_status not in ('MERGED', 'INVALID'))

and id != #{excludeId,jdbcType=INTEGER}
and owner_id = #{dataScopeUserId,jdbcType=INTEGER}
order by create_time desc, id desc
limit #{limit}

mapper.update:
update t_customer
set owner_id = #{toOwnerId,jdbcType=INTEGER},
    edit_by = #{editBy,jdbcType=INTEGER},
    edit_time = CURRENT_TIMESTAMP
where id = #{id,jdbcType=INTEGER}
  and owner_id = #{fromOwnerId,jdbcType=INTEGER}
  and (customer_status is null or customer_status != 'MERGED')
  and owner_id = #{dataScopeUserId,jdbcType=INTEGER}

